-- Mayon Daily Walkthrough Housekeeping Checklist — the first facility
-- checklist, conducted by QA/admin (requires_audit_type) against the
-- "Mayon Building" facility added in the foundation migration. Point-
-- weighted (pts per item, 1 or 5 here) rather than equal-weight — Audit.jsx
-- sums pts for yes/no/na instead of counting items when a template uses
-- them, so the score is "points earned / points applicable" like the
-- original paper checklist.
--
-- Pass threshold is 92.5% per standing instruction (every QA checklist
-- uses 92.5%, regardless of what any source document says) — NOT the 93%
-- printed on this checklist's own Front Cover.
--
-- Two of this checklist's own section "Total" cells don't match the sum of
-- their items (Third Floor Lobby prints 9, items sum to 10; Third Floor
-- Office prints 15, items sum to 48) — likely stale totals from edits made
-- after the sheet's summary row was last updated. Scoring here is always
-- computed live from the item list, same as every other checklist, so this
-- doesn't affect correctness — flagging only in case the source workbook
-- itself is worth fixing.
INSERT INTO public.audit_templates (
  id, title, description, sections, is_active, template_group, active_ticket,
  pass_threshold, requires_audit_type, requires_visit_number, requires_commitment_date,
  has_time_restriction, available_from_time, available_to_time,
  store_restrictions, brand_id, brand_name, store_id, store_name,
  created_date, updated_date
)
SELECT
  gen_random_uuid()::text,
  'Mayon Daily Walkthrough Housekeeping Checklist',
