  true, 'others', false,
  92.5, true, false, true,
  false, '', '',
  jsonb_build_array(jsonb_build_object(
    'brand_id', b.id, 'brand_name', b.brand_name,
    'store_id', s.id, 'store_name', s.store_name
  )),
  b.id, b.brand_name, s.id, s.store_name,
  now(), now()
FROM public.brands b
JOIN public.stores s ON s.brand_id = b.id AND s.store_name = 'Mayon Building'
WHERE b.brand_name = 'Head Office'
  AND NOT EXISTS (
    SELECT 1 FROM public.audit_templates WHERE title = 'Mayon Daily Walkthrough Housekeeping Checklist'
  );
